// Omniflow batch 236-250 — CUSTOMER SEGMENTS v1: saved deterministic filters,
// live member audiences, segment broadcast (WATI-style targeting).
// Run from the folder that contains BOTH repos (Omniflow/ and OmniFlow-Control-Plane/):
//   node add_batch_236_250.mjs
// CP:  NEW portal_segments.py — lazy portal_segments(id, client_id, name, filters JSONB);
//      strict allow-list filter validation (lead_temp hot|warm|cold, status open|closed,
//      idle_days 1-365 HAVING MAX(last_message_at), tag EXISTS on portal_conversation_tags);
//      GET /portal/segments (live member_count per segment), POST /portal/segments,
//      DELETE /portal/segments/<id>, GET /portal/segments/<id>/members (cap 500),
//      POST /portal/segments/<id>/broadcast — personalized {name} WhatsApp send to every
//      member via the existing command queue (cap 200, source "segment", 400 when empty,
//      audits segment.created/deleted/broadcast). app.py registers the blueprint
//      (single-line anchors on the portal_cod lines, same pattern as every prior module).
// Web: portal.ts SegmentFilters/SegmentRow/SegmentMember + list/create/delete/members/
//      broadcast clients (filters normalizer, count/sent parsing); FOUR BFF routes
//      (segments 5 ups, [id] 6 ups, members+broadcast 7 ups per the depth law);
//      NEW /dashboard/segments page (filter pickers + live counts + People preview +
//      broadcast dialog with {name} and no-member warning) + sidebar "Segments" item.
// Tests (rig, not this patcher): test_segments.py 38, test_segments_ui.py 34.
// Idempotent: re-run reports "already done" per block. Backups: *.pre_b236250.bak
import fs from "fs";
import { createRequire } from "module";
const require = createRequire(import.meta.url);

const BACKUP_TAG = ".pre_b236250.bak";
let applied = 0;
let already = 0;
let warnings = 0;

function compilePython(pathArg) {
  const { spawnSync } = require("child_process");
  for (const py of ["python3", "python", "py"]) {
    const probe = spawnSync(py, ["--version"], { encoding: "utf8" });
    if (probe.status !== 0) continue;
    const check = spawnSync(py, ["-c", "import sys;sys.exit(0 if sys.version_info[0]>=3 else 1)"], { encoding: "utf8" });
    if (check.status !== 0) continue;
    const result = spawnSync(py, ["-c", "import py_compile,sys;py_compile.compile(sys.argv[1],doraise=True);sys.exit(0)", pathArg], { encoding: "utf8" });
    return result.status === 0;
  }
  console.log("  (python not found — skipped compile guard)");
  return true;
}

function applySwaps(repoPath, marker, isCp, swaps) {
  if (!fs.existsSync(repoPath)) {
    console.log("SKIP (file not found): " + repoPath);
    warnings++;
    return;
  }
  const original = fs.readFileSync(repoPath, "utf8").replace(/\r\n/g, "\n");
  if (original.includes(marker)) {
    console.log("= " + repoPath + " (already patched)");
    already++;
    return;
  }
  const backup = repoPath + BACKUP_TAG;
  if (!fs.existsSync(backup)) fs.copyFileSync(repoPath, backup);
  let updated = original;
  let ok = true;
  for (const [frm, to] of swaps) {
    if (!updated.includes(frm)) {
      console.log("  ? " + repoPath + " :: anchor NOT FOUND — report this");
      ok = false;
      warnings++;
      break;
    }
    updated = updated.replace(frm, to);
  }
  if (!ok) return;
  fs.writeFileSync(repoPath, updated, "utf8");
  if (isCp && !compilePython(repoPath)) {
    fs.copyFileSync(backup, repoPath);
    console.log("FAIL (compile failed, restored): " + repoPath);
    warnings++;
    return;
  }
  console.log("+ " + repoPath + " (" + swaps.length + ")");
  applied++;
}

function writeNew(repoPath, marker, isCp, content) {
  if (!fs.existsSync(repoPath)) {
    fs.mkdirSync(repoPath.replace(/\/[^/]*$/, ""), { recursive: true });
    fs.writeFileSync(repoPath, content, "utf8");
    if (isCp && !compilePython(repoPath)) {
      console.log("FAIL (compile failed): " + repoPath);
      warnings++;
      return;
    }
    console.log("+ " + repoPath + " (new file)");
    applied++;
    return;
  }
  const original = fs.readFileSync(repoPath, "utf8").replace(/\r\n/g, "\n");
  if (original.includes(marker)) {
    console.log("= " + repoPath + " (already patched)");
    already++;
    return;
  }
  console.log("  ? " + repoPath + " exists WITHOUT marker — report this");
  warnings++;
}


