writeNew("OmniFlow-Control-Plane/portal_segments.py", "portal_segments", true,
"\"\"\"Deterministic customer segments: saved filters that resolve to live audiences.\"\"\"\n\nimport json\nimport logging\nfrom typing import Any, Dict, Optional, Tuple\n\nfrom flask import Blueprint, jsonify, request\n\nfrom portal_auth import (\n    PortalAuthUnavailable,\n    authenticate_portal_request,\n    ensure_human_principal,\n)\nimport portal_db\nimport portal_growth\n\nbp = Blueprint(\"portal_segments\", __name__, url_prefix=\"/api/v1/portal\")\n\nlogger = logging.getLogger(__name__)\n\nSEGMENTS_TABLE = \"portal_segments\"\nMAX_NAME = 80\nMAX_BODY = 1000\nMEMBER_CAP = 500\nBROADCAST_CAP = 200\nVALID_LEAD_TEMP = (\"hot\", \"warm\", \"cold\")\nVALID_STATUS = (\"open\", \"closed\")\n\n_SEG_DDL_READY = False\n\n\ndef _principal_or_error():\n    try:\n        principal = authenticate_portal_request()\n    except PortalAuthUnavailable as error:\n        return None, (jsonify({\"error\": {\"code\": \"portal_unavailable\",\n                                         \"message\": str(error)}}), 503)\n    if principal is None:\n        return None, (jsonify({\"error\": {\"code\": \"unauthorized\",\n                                         \"message\": \"Sign in required.\"}}), 401)\n    return principal, None\n\n\ndef _iso(value: Any) -> Optional[str]:\n    if value is None:\n        return None\n    try:\n        return value.isoformat()\n    except AttributeError:\n        return None\n\n\ndef _ensure_seg_tables(conn) -> None:\n    global _SEG_DDL_READY\n    if _SEG_DDL_READY:\n        return\n    with conn.cursor() as cur:\n        cur.execute(\n            \"CREATE TABLE IF NOT EXISTS \" + portal_db._q(SEGMENTS_TABLE) +\n            \" (id BIGSERIAL PRIMARY KEY,\"\n            \" client_id BIGINT NOT NULL,\"\n            \" name TEXT NOT NULL,\"\n            \" filters JSONB NOT NULL,\"\n            \" created_at TIMESTAMPTZ NOT NULL DEFAULT NOW())\"\n        )\n    conn.commit()\n    _SEG_DDL_READY = True\n\n\ndef _parse_filters(raw: Any) -> Optional[Dict[str, Any]]:\n    \"\"\"Strict allow-list validation; returns the clean dict or None.\"\"\"\n    if not isinstance(raw, dict):\n        return None\n    clean: Dict[str, Any] = {}\n    if \"lead_temp\" in raw:\n        value = raw[\"lead_temp\"]\n        if value not in VALID_LEAD_TEMP:\n            return None\n        clean[\"lead_temp\"] = value\n    if \"status\" in raw:\n        value = raw[\"status\"]\n        if value not in VALID_STATUS:\n            return None\n        clean[\"status\"] = value\n    if \"idle_days\" in raw:\n        value = raw[\"idle_days\"]\n        if isinstance(value, bool) or not isinstance(value, int):\n            return None\n        if value < 1 or value > 365:\n            return None\n        clean[\"idle_days\"] = value\n    if \"tag\" in raw:\n        value = str(raw[\"tag\"] or \"\").strip()[:32]\n        if not value:\n            return None\n        clean[\"tag\"] = value\n    if not clean:\n        return None\n    return clean\n\n\ndef _member_rows(cur, client_id: int, filters: Dict[str, Any],\n                 limit: int) -> list:\n    sql = (\n        \"SELECT c.contact_id,\"\n        \" MAX(c.contact_name) AS name,\"\n        \" MAX(c.last_message_at) AS last_at,\"\n        \" COUNT(*) AS chats\"\n        \" FROM \" + portal_db._q(portal_db.CONV_TABLE) + \" c\"\n        \" WHERE c.client_id = %s\"\n    )\n    params: list = [client_id]\n    if \"lead_temp\" in filters:\n        sql += \" AND c.lead_temp = %s\"\n        params.append(filters[\"lead_temp\"])\n    if \"status\" in filters:\n        sql += \" AND c.status = %s\"\n        params.append(filters[\"status\"])\n    if \"tag\" in filters:\n        sql += (\n            \" AND EXISTS (SELECT 1 FROM \" +\n            portal_db._q(portal_db.CONV_TAGS_TABLE) +\n            \" ct WHERE ct.conversation_id = c.id\"\n            \" AND ct.client_id = c.client_id\"\n            \" AND LOWER(ct.tag) = LOWER(%s))\"\n        )\n        params.append(filters[\"tag\"])\n    sql += \" GROUP BY c.contact_id\"\n    if \"idle_days\" in filters:\n        sql += (\" HAVING MAX(c.last_message_at)\"\n                \" < NOW() - make_interval(days => %s)\")\n        params.append(int(filters[\"idle_days\"]))\n    sql += \" ORDER BY MAX(c.last_message_at) DESC NULLS LAST, c.contact_id\"\n    sql += \" LIMIT %s\"\n    params.append(int(limit))\n    cur.execute(sql, tuple(params))\n    return portal_db.rows(cur)\n\n\ndef _member_count(cur, client_id: int, filters: Dict[str, Any]) -> int:\n    rows = _member_rows(cur, client_id, filters, MEMBER_CAP)\n    return len(rows)\n\n\ndef _segment_public(row: Dict[str, Any], member_count: int) -> dict:\n    filters = row.get(\"filters\")\n    if isinstance(filters, str):\n        try:\n            filters = json.loads(filters)\n        except (TypeError, ValueError):\n            filters = {}\n    return {\n        \"id\": row.get(\"id\"),\n        \"name\": row.get(\"name\") or \"\",\n        \"filters\": filters or {},\n        \"member_count\": member_count,\n        \"created_at\": _iso(row.get(\"created_at\")),\n    }\n\n\n@bp.get(\"/segments\")\ndef list_segments():\n    principal, error = _principal_or_error()\n    if error:\n        return error\n    try:\n        portal_db.ensure_tables()\n        conn = portal_db._conn()\n        try:\n            _ensure_seg_tables(conn)\n            with conn.cursor() as cur:\n                cur.execute(\n                    \"SELECT id, name, filters, created_at FROM \" +\n                    portal_db._q(SEGMENTS_TABLE) +\n                    \" WHERE client_id = %s ORDER BY id DESC LIMIT 20\",\n                    (principal[\"client_id\"],),\n                )\n                rows = portal_db.rows(cur)\n                result = []\n                for row in rows:\n                    filters = row.get(\"filters\")\n                    if isinstance(filters, str):\n                        try:\n                            filters = json.loads(filters)\n                        except (TypeError, ValueError):\n                            filters = {}\n                    count = _member_count(cur, principal[\"client_id\"],\n                                          filters or {})\n                    result.append(_segment_public(row, count))\n        finally:\n            conn.close()\n    except Exception as error:\n        logger.warning(\"segments read failed: %s\", error)\n        return jsonify(portal_db.portal_unavailable(error, \"segments read\")[0]), 503\n    return jsonify({\"segments\": result}), 200\n\n\n@bp.post(\"/segments\")\ndef create_segment():\n    principal, error = _principal_or_error()\n    if error:\n        return error\n    forbidden = ensure_human_principal(principal)\n    if forbidden is not None:\n        return forbidden\n    payload = request.get_json(silent=True) or {}\n    name = str(payload.get(\"name\") or \"\").strip()[:MAX_NAME]\n    if not name:\n        return jsonify({\"error\": {\"code\": \"bad_request\",\n                                  \"message\": \"A name is required.\"}}), 400\n    filters = _parse_filters(payload.get(\"filters\"))\n    if filters is None:\n        return jsonify({\"error\": {\"code\": \"bad_request\",\n                                  \"message\": \"Pick at least one valid filter\"\n                                             \" (lead_temp hot/warm/cold, status\"\n                                             \" open/closed, idle_days 1-365,\"\n                                             \" tag).\"}}), 400\n    try:\n        portal_db.ensure_tables()\n        conn = portal_db._conn()\n        try:\n            _ensure_seg_tables(conn)\n            with conn.cursor() as cur:\n                cur.execute(\n                    \"INSERT INTO \" + portal_db._q(SEGMENTS_TABLE) +\n                    \" (client_id, name, filters)\"\n                    \" VALUES (%s, %s, %s::jsonb)\"\n                    \" RETURNING id, name, filters, created_at\",\n                    (principal[\"client_id\"], name,\n                     json.dumps(filters)),\n                )\n                rows = portal_db.rows(cur)\n                created = rows[0] if rows else {}\n                count = _member_count(cur, principal[\"client_id\"], filters)\n                portal_db.log_action(\n                    cur,\n                    principal[\"client_id\"],\n                    \"segment.created\",\n                    \"customer_user\",\n                    principal.get(\"user_id\"),\n                    None,\n                    \"Segment '\" + name + \"' with filters \"\n                    + json.dumps(filters) + \".\",\n                )\n            conn.commit()\n        finally:\n            conn.close()\n    except Exception as error:\n        return jsonify(portal_db.portal_unavailable(error, \"segment create\")[0]), 503\n    return jsonify({\"ok\": True,\n                    \"segment\": _segment_public(created, count)}), 200\n\n\ndef _load_segment(cur, client_id: int, segment_id: int) -> Optional[dict]:\n    cur.execute(\n        \"SELECT id, name, filters, created_at FROM \" +\n        portal_db._q(SEGMENTS_TABLE) +\n        \" WHERE id = %s AND client_id = %s\",\n        (segment_id, client_id),\n    )\n    rows = portal_db.rows(cur)\n    return rows[0] if rows else None\n\n\n@bp.get(\"/segments/<int:segment_id>/members\")\ndef segment_members(segment_id: int):\n    principal, error = _principal_or_error()\n    if error:\n        return error\n    try:\n        raw_limit = request.args.get(\"limit\")\n        limit = int(raw_limit) if raw_limit else 100\n    except (TypeError, ValueError):\n        limit = 100\n    limit = max(1, min(MEMBER_CAP, limit))\n    try:\n        portal_db.ensure_tables()\n        conn = portal_db._conn()\n        try:\n            _ensure_seg_tables(conn)\n            with conn.cursor() as cur:\n                row = _load_segment(cur, principal[\"client_id\"], segment_id)\n                if not row:\n                    return jsonify({\"error\": {\"code\": \"not_found\",\n                                              \"message\": \"Segment not found.\"}}), 404\n                filters = row.get(\"filters\")\n                if isinstance(filters, str):\n                    try:\n                        filters = json.loads(filters)\n                    except (TypeError, ValueError):\n                        filters = {}\n                rows = _member_rows(cur, principal[\"client_id\"],\n                                    filters or {}, limit)\n        finally:\n            conn.close()\n    except Exception as error:\n        return jsonify(portal_db.portal_unavailable(error, \"segment members\")[0]), 503\n    return jsonify({\"members\": [\n        {\n            \"contact_id\": row.get(\"contact_id\") or \"\",\n            \"name\": row.get(\"name\") or \"\",\n            \"chats\": int(row.get(\"chats\") or 0),\n            \"last_at\": _iso(row.get(\"last_at\")),\n        }\n        for row in rows\n    ]}), 200\n\n\n@bp.delete(\"/segments/<int:segment_id>\")\ndef delete_segment(segment_id: int):\n    principal, error = _principal_or_error()\n    if error:\n        return error\n    forbidden = ensure_human_principal(principal)\n    if forbidden is not None:\n        return forbidden\n    try:\n        portal_db.ensure_tables()\n        conn = portal_db._conn()\n        try:\n            _ensure_seg_tables(conn)\n            with conn.cursor() as cur:\n                cur.execute(\n                    \"DELETE FROM \" + portal_db._q(SEGMENTS_TABLE) +\n                    \" WHERE id = %s AND client_id = %s RETURNING id\",\n                    (segment_id, principal[\"client_id\"]),\n                )\n                rows = portal_db.rows(cur)\n                if rows:\n                    portal_db.log_action(\n                        cur,\n                        principal[\"client_id\"],\n                        \"segment.deleted\",\n                        \"customer_user\",\n                        principal.get(\"user_id\"),\n                        None,\n                        \"Segment #%d deleted.\" % segment_id,\n                    )\n            conn.commit()\n        finally:\n            conn.close()\n    except Exception as error:\n        return jsonify(portal_db.portal_unavailable(error, \"segment delete\")[0]), 503\n    if not rows:\n        return jsonify({\"error\": {\"code\": \"not_found\",\n                                  \"message\": \"Segment not found.\"}}), 404\n    return jsonify({\"ok\": True}), 200\n\n\n@bp.post(\"/segments/<int:segment_id>/broadcast\")\ndef segment_broadcast(segment_id: int):\n    \"\"\"Send a WhatsApp message to every member of the segment, right now.\"\"\"\n    principal, error = _principal_or_error()\n    if error:\n        return error\n    forbidden = ensure_human_principal(principal)\n    if forbidden is not None:\n        return forbidden\n    payload = request.get_json(silent=True) or {}\n    body = str(payload.get(\"body\") or \"\").strip()[:MAX_BODY]\n    if not body:\n        return jsonify({\"error\": {\"code\": \"bad_request\",\n                                  \"message\": \"A message is required.\"}}), 400\n    try:\n        portal_db.ensure_tables()\n        conn = portal_db._conn()\n        try:\n            _ensure_seg_tables(conn)\n            with conn.cursor() as cur:\n                row = _load_segment(cur, principal[\"client_id\"], segment_id)\n                if not row:\n                    return jsonify({\"error\": {\"code\": \"not_found\",\n                                              \"message\": \"Segment not found.\"}}), 404\n                filters = row.get(\"filters\")\n                if isinstance(filters, str):\n                    try:\n                        filters = json.loads(filters)\n                    except (TypeError, ValueError):\n                        filters = {}\n                members = _member_rows(cur, principal[\"client_id\"],\n                                       filters or {}, BROADCAST_CAP)\n                if not members:\n                    return jsonify({\"error\": {\"code\": \"bad_request\",\n                                              \"message\": \"No members match this\"\n                                                         \" segment right now.\"}}), 400\n                for member in members:\n                    display = str(member.get(\"name\") or \"\").strip()\n                    text = body.replace(\n                        \"{name}\", (display.split(\" \")[0] if display else \"there\")\n                    )\n                    portal_growth._send_command(\n                        cur, principal[\"client_id\"],\n                        str(member.get(\"contact_id\") or \"\"), display,\n                        text, \"segment\", broadcast_id=None,\n                    )\n                portal_db.log_action(\n                    cur,\n                    principal[\"client_id\"],\n                    \"segment.broadcast\",\n                    \"customer_user\",\n                    principal.get(\"user_id\"),\n                    None,\n                    \"Broadcast to segment '\" + str(row.get(\"name\") or \"\")\n                    + \"' (\" + str(len(members)) + \" member(s)).\",\n                )\n            conn.commit()\n        finally:\n            conn.close()\n    except Exception as error:\n        return jsonify(portal_db.portal_unavailable(error, \"segment broadcast\")[0]), 503\n    return jsonify({\"ok\": True, \"sent\": len(members)}), 200\n");


writeNew("Omniflow/app/dashboard/(portal)/segments/page.tsx", "Send broadcast", false,
"\"use client\";\n\nimport { useCallback, useEffect, useState } from \"react\";\n\ninterface SegmentFilters {\n  lead_temp?: string;\n  status?: string;\n  idle_days?: number;\n  tag?: string;\n}\n\ninterface Segment {\n  id: number;\n  name: string;\n  filters: SegmentFilters;\n  memberCount: number;\n}\n\ninterface Member {\n  contactId: string;\n  name: string;\n  chats: number;\n  lastAt: string | null;\n}\n\nconst LEAD_OPTIONS = [\n  { value: \"\", label: \"Any lead temperature\" },\n  { value: \"hot\", label: \"Hot leads\" },\n  { value: \"warm\", label: \"Warm leads\" },\n  { value: \"cold\", label: \"Cold leads\" },\n];\n\nconst STATUS_OPTIONS = [\n  { value: \"\", label: \"Any chat status\" },\n  { value: \"open\", label: \"Has an open chat\" },\n  { value: \"closed\", label: \"Only closed chats\" },\n];\n\nfunction describe(filters: SegmentFilters): string {\n  const parts: string[] = [];\n  if (filters.lead_temp) parts.push(filters.lead_temp + \" leads\");\n  if (filters.status === \"open\") parts.push(\"open chat\");\n  if (filters.status === \"closed\") parts.push(\"closed chats\");\n  if (filters.idle_days) parts.push(\"quiet for \" + filters.idle_days + \"d\");\n  if (filters.tag) parts.push(\"tagged \" + filters.tag);\n  return parts.join(\" \\u00b7 \");\n}\n\nexport default function SegmentsPage() {\n  const [segments, setSegments] = useState<Segment[] | null>(null);\n  const [name, setName] = useState(\"\");\n  const [leadTemp, setLeadTemp] = useState(\"\");\n  const [status, setStatus] = useState(\"\");\n  const [idleDays, setIdleDays] = useState(\"\");\n  const [tag, setTag] = useState(\"\");\n  const [busy, setBusy] = useState(false);\n  const [note, setNote] = useState(\"\");\n  const [noteTone, setNoteTone] = useState(\"neutral\");\n  const [openMembers, setOpenMembers] = useState<number | null>(null);\n  const [members, setMembers] = useState<Member[]>([]);\n  const [castOpenFor, setCastOpenFor] = useState<number | null>(null);\n  const [castDraft, setCastDraft] = useState(\"\");\n  const [castBusy, setCastBusy] = useState(false);\n  const [castNote, setCastNote] = useState<string | null>(null);\n\n  const load = useCallback(async () => {\n    try {\n      const response = await fetch(\"/api/omniflow/portal/segments\", {\n        cache: \"no-store\",\n      });\n      const payload: unknown = await response.json().catch(() => null);\n      if (payload !== null && typeof payload === \"object\") {\n        const list = (payload as { segments?: Segment[] }).segments;\n        setSegments(Array.isArray(list) ? list : []);\n      }\n    } catch {\n      setSegments([]);\n    }\n  }, []);\n\n  useEffect(() => {\n    void load();\n  }, [load]);\n\n  const create = useCallback(async () => {\n    if (busy) return;\n    const filters: SegmentFilters = {};\n    if (leadTemp) filters.lead_temp = leadTemp;\n    if (status) filters.status = status;\n    if (idleDays) {\n      const days = Number(idleDays);\n      if (!Number.isInteger(days) || days < 1 || days > 365) {\n        setNoteTone(\"amber\");\n        setNote(\"Idle days must be 1-365.\");\n        return;\n      }\n      filters.idle_days = days;\n    }\n    if (tag.trim()) filters.tag = tag.trim();\n    if (!name.trim() || Object.keys(filters).length === 0) {\n      setNoteTone(\"amber\");\n      setNote(\"Give the segment a name and at least one filter.\");\n      return;\n    }\n    setBusy(true);\n    setNote(\"\");\n    try {\n      const response = await fetch(\"/api/omniflow/portal/segments\", {\n        method: \"POST\",\n        headers: { \"Content-Type\": \"application/json\" },\n        body: JSON.stringify({ name: name.trim(), filters }),\n      });\n      if (response.ok) {\n        setNoteTone(\"emerald\");\n        setNote(\"Segment saved. Counts update live.\");\n        setName(\"\");\n        setLeadTemp(\"\");\n        setStatus(\"\");\n        setIdleDays(\"\");\n        setTag(\"\");\n        void load();\n        return;\n      }\n      setNoteTone(\"amber\");\n      setNote(\"Could not save. Check the filters.\");\n    } catch {\n      setNoteTone(\"amber\");\n      setNote(\"Could not save. Try again.\");\n    } finally {\n      setBusy(false);\n    }\n  }, [busy, idleDays, leadTemp, load, name, status, tag]);\n\n  const showMembers = useCallback(\n    async (id: number) => {\n      if (openMembers === id) {\n        setOpenMembers(null);\n        return;\n      }\n      setOpenMembers(id);\n      setMembers([]);\n      try {\n        const response = await fetch(\n          \"/api/omniflow/portal/segments/\" + String(id) + \"/members\",\n          { cache: \"no-store\" }\n        );\n        const payload: unknown = await response.json().catch(() => null);\n        if (payload !== null && typeof payload === \"object\") {\n          const list = (payload as { members?: Member[] }).members;\n          setMembers(Array.isArray(list) ? list : []);\n        }\n      } catch {\n        setMembers([]);\n      }\n    },\n    [openMembers]\n  );\n\n  const remove = useCallback(\n    async (row: Segment) => {\n      setBusy(true);\n      try {\n        await fetch(\"/api/omniflow/portal/segments/\" + String(row.id), {\n          method: \"DELETE\",\n        });\n        void load();\n      } catch {\n        void load();\n      } finally {\n        setBusy(false);\n      }\n    },\n    [load]\n  );\n\n  const openCast = useCallback((row: Segment) => {\n    setCastOpenFor(row.id);\n    setCastDraft(\"\");\n    setCastNote(null);\n  }, []);\n\n  const sendCast = useCallback(\n    async (row: Segment) => {\n      if (castBusy || !castDraft.trim()) return;\n      setCastBusy(true);\n      setCastNote(null);\n      try {\n        const response = await fetch(\n          \"/api/omniflow/portal/segments/\" + String(row.id) + \"/broadcast\",\n          {\n            method: \"POST\",\n            headers: { \"Content-Type\": \"application/json\" },\n            body: JSON.stringify({ body: castDraft.trim() }),\n          }\n        );\n        const payload = (await response.json().catch(() => null)) as {\n          sent?: number;\n        } | null;\n        if (response.ok && payload && typeof payload.sent === \"number\") {\n          setCastOpenFor(null);\n          setNoteTone(\"emerald\");\n          setNote(\"Broadcast queued to \" + payload.sent + \" member(s).\");\n          void load();\n          return;\n        }\n        setCastNote(\n          response.status === 400\n            ? \"No members match this segment right now.\"\n            : \"Could not send. Try again.\"\n        );\n      } catch {\n        setCastNote(\"Could not send. Try again.\");\n      } finally {\n        setCastBusy(false);\n      }\n    },\n    [castBusy, castDraft, load]\n  );\n\n  return (\n    <main className=\"min-h-screen bg-[#07111f] px-4 py-8 sm:px-6\">\n      <div className=\"mx-auto max-w-3xl\">\n        <div className=\"mb-6\">\n          <p className=\"mb-1 text-[10px] font-medium uppercase tracking-[0.2em] text-cyan-400/70\">\n            OmniFlow\n          </p>\n          <h1 className=\"text-2xl font-semibold text-white\">Segments</h1>\n          <p className=\"mt-1 text-sm text-slate-500\">\n            Save customer groups with simple filters, then message the whole\n            group. Counts stay live.\n          </p>\n        </div>\n\n        <div className=\"rounded-2xl border border-white/[0.06] bg-white/[0.015] p-5\">\n          <p className=\"text-sm font-medium text-slate-200\">New segment</p>\n          <input\n            value={name}\n            onChange={(event) => setName(event.target.value)}\n            placeholder=\"Group name, e.g. Hot leads gone quiet\"\n            className=\"mt-3 w-full rounded-xl border border-white/[0.07] bg-white/[0.02] px-3.5 py-2.5 text-sm text-white placeholder:text-slate-600 outline-none transition-colors duration-300 focus:border-cyan-400/40\"\n          />\n          <div className=\"mt-2 grid gap-2 sm:grid-cols-2\">\n            <select\n              value={leadTemp}\n              onChange={(event) => setLeadTemp(event.target.value)}\n              className=\"rounded-xl border border-white/[0.07] bg-white/[0.02] px-3 py-2.5 text-sm text-white outline-none focus:border-cyan-400/40\"\n            >\n              {LEAD_OPTIONS.map((option) => (\n                <option key={option.value} value={option.value} className=\"bg-slate-900\">\n                  {option.label}\n                </option>\n              ))}\n            </select>\n            <select\n              value={status}\n              onChange={(event) => setStatus(event.target.value)}\n              className=\"rounded-xl border border-white/[0.07] bg-white/[0.02] px-3 py-2.5 text-sm text-white outline-none focus:border-cyan-400/40\"\n            >\n              {STATUS_OPTIONS.map((option) => (\n                <option key={option.value} value={option.value} className=\"bg-slate-900\">\n                  {option.label}\n                </option>\n              ))}\n            </select>\n            <input\n              type=\"number\"\n              min={1}\n              max={365}\n              value={idleDays}\n              onChange={(event) => setIdleDays(event.target.value)}\n              placeholder=\"Quiet for N days (optional)\"\n              className=\"rounded-xl border border-white/[0.07] bg-white/[0.02] px-3.5 py-2.5 text-sm text-white placeholder:text-slate-600 outline-none focus:border-cyan-400/40\"\n            />\n            <input\n              value={tag}\n              onChange={(event) => setTag(event.target.value)}\n              placeholder=\"Tagged with (optional)\"\n              className=\"rounded-xl border border-white/[0.07] bg-white/[0.02] px-3.5 py-2.5 text-sm text-white placeholder:text-slate-600 outline-none focus:border-cyan-400/40\"\n            />\n          </div>\n          <div className=\"mt-3 flex flex-wrap items-center gap-3\">\n            <button\n              type=\"button\"\n              onClick={() => void create()}\n              disabled={busy}\n              className=\"rounded-xl bg-cyan-400/15 px-4 py-2 text-sm font-medium text-cyan-200 transition hover:bg-cyan-400/25 disabled:opacity-50\"\n            >\n              {busy ? \"Working\\u2026\" : \"Save segment\"}\n            </button>\n            {note ? (\n              <p\n                className={\n                  \"text-xs \" +\n                  (noteTone === \"emerald\" ? \"text-emerald-300\" : \"text-amber-300\")\n                }\n              >\n                {note}\n              </p>\n            ) : null}\n          </div>\n        </div>\n\n        {segments === null ? (\n          <p className=\"text-sm text-slate-500\">Loading\\u2026</p>\n        ) : segments.length === 0 ? (\n          <div className=\"rounded-2xl border border-white/[0.06] bg-white/[0.015] px-5 py-8 text-center\">\n            <p className=\"text-sm text-slate-400\">No segments yet.</p>\n            <p className=\"mt-1 text-xs text-slate-600\">\n              Save your first group above \\u2014 hot leads, quiet customers, tagged VIPs.\n            </p>\n          </div>\n        ) : (\n          <ul className=\"space-y-2\">\n            {segments.map((row) => (\n              <li\n                key={row.id}\n                className=\"rounded-2xl border border-white/[0.06] bg-white/[0.015] p-4\"\n              >\n                <div className=\"flex flex-col gap-2 sm:flex-row sm:items-center sm:justify-between\">\n                  <div className=\"min-w-0\">\n                    <p className=\"truncate text-sm font-medium text-slate-200\">\n                      {row.name}\n                    </p>\n                    <p className=\"mt-0.5 text-[11px] text-slate-500\">\n                      {describe(row.filters) || \"No filters\"} \\u00b7{\" \"}\n                      <span className=\"text-cyan-300\">{row.memberCount}</span>{\" \"}\n                      member{row.memberCount === 1 ? \"\" : \"s\"}\n                    </p>\n                  </div>\n                  <div className=\"flex shrink-0 items-center gap-2\">\n                    <button\n                      type=\"button\"\n                      onClick={() => void showMembers(row.id)}\n                      className=\"rounded-lg border border-white/[0.08] px-3 py-1.5 text-xs text-slate-300 transition hover:text-white\"\n                    >\n                      {openMembers === row.id ? \"Hide people\" : \"People\"}\n                    </button>\n                    <button\n                      type=\"button\"\n                      onClick={() => openCast(row)}\n                      className=\"rounded-lg border border-cyan-400/25 bg-cyan-400/[0.08] px-3 py-1.5 text-xs font-medium text-cyan-200 transition hover:bg-cyan-400/[0.14]\"\n                    >\n                      Send broadcast\n                    </button>\n                    <button\n                      type=\"button\"\n                      onClick={() => void remove(row)}\n                      className=\"rounded-lg border border-white/[0.08] px-3 py-1.5 text-xs text-slate-300 transition hover:border-rose-400/40 hover:text-rose-300\"\n                    >\n                      Delete\n                    </button>\n                  </div>\n                </div>\n                {openMembers === row.id ? (\n                  <div className=\"mt-3 rounded-xl border border-white/[0.06] bg-white/[0.01] p-3\">\n                    {members.length === 0 ? (\n                      <p className=\"text-xs text-slate-500\">\n                        No members match right now.\n                      </p>\n                    ) : (\n                      <ul className=\"space-y-1.5\">\n                        {members.map((member) => (\n                          <li\n                            key={member.contactId}\n                            className=\"flex items-center justify-between gap-2 text-xs\"\n                          >\n                            <span className=\"truncate text-slate-300\">\n                              {member.name || \"Customer\"}\n                            </span>\n                            <span className=\"shrink-0 text-slate-500\">\n                              {member.chats} chat{member.chats === 1 ? \"\" : \"s\"}\n                            </span>\n                          </li>\n                        ))}\n                      </ul>\n                    )}\n                  </div>\n                ) : null}\n                {castOpenFor === row.id ? (\n                  <div className=\"mt-3 rounded-xl border border-white/[0.06] bg-white/[0.01] p-3\">\n                    <p className=\"text-[11px] uppercase tracking-wider text-slate-500\">\n                      Message everyone in {row.name}\n                    </p>\n                    <textarea\n                      value={castDraft}\n                      onChange={(event) => setCastDraft(event.target.value)}\n                      rows={2}\n                      maxLength={1000}\n                      placeholder=\"Use {name} for the customer's first name.\"\n                      className=\"mt-2 w-full rounded-lg border border-white/[0.07] bg-white/[0.02] px-3 py-2 text-sm text-white placeholder:text-slate-600 outline-none focus:border-cyan-400/40\"\n                    />\n                    <div className=\"mt-2 flex flex-wrap items-center gap-2\">\n                      <button\n                        type=\"button\"\n                        onClick={() => void sendCast(row)}\n                        disabled={castBusy}\n                        className=\"rounded-lg border border-cyan-400/25 bg-cyan-400/[0.08] px-3 py-1.5 text-xs font-medium text-cyan-200 transition hover:bg-cyan-400/[0.14] disabled:opacity-50\"\n                      >\n                        {castBusy ? \"Sending...\" : \"Send now\"}\n                      </button>\n                      <button\n                        type=\"button\"\n                        onClick={() => setCastOpenFor(null)}\n                        className=\"rounded-lg border border-white/[0.08] px-3 py-1.5 text-xs text-slate-300 transition hover:text-white\"\n                      >\n                        Close\n                      </button>\n                      {castNote ? (\n                        <p className=\"text-xs text-amber-300\">{castNote}</p>\n                      ) : null}\n                    </div>\n                    <p className=\"mt-2 text-[10px] text-slate-600\">\n                      Delivered through your WhatsApp queue, up to 200 members per\n                      send.\n                    </p>\n                  </div>\n                ) : null}\n              </li>\n            ))}\n          </ul>\n        )}\n      </div>\n    </main>\n  );\n}\n");


writeNew("Omniflow/app/api/omniflow/portal/segments/route.ts", "createSegment", false,
"import {\n  createSegment,\n  listSegments,\n  requirePortalAccessToken,\n} from \"../../../../../lib/omniflow/portal\";\nimport {\n  noStoreHeaders,\n  safeJson,\n} from \"../../../../../lib/omniflow/request-security\";\nimport { ControlPlaneRequestError } from \"../../../../../lib/omniflow/control-plane\";\n\n\nexport async function GET() {\n  const accessToken = await requirePortalAccessToken();\n  if (!accessToken) {\n    return safeJson(\n      { error: { code: \"unauthorized\", message: \"Sign in required.\" } },\n      401\n    );\n  }\n\n  try {\n    const segments = await listSegments(accessToken);\n    return safeJson({ segments }, 200);\n  } catch (error) {\n    if (error instanceof ControlPlaneRequestError && error.isUnauthorized) {\n      return safeJson(\n        { error: { code: \"unauthorized\", message: \"Session expired.\" } },\n        401\n      );\n    }\n    return safeJson(\n      { error: { code: \"portal_unavailable\", message: \"Try again shortly.\" } },\n      503\n    );\n  }\n}\n\nexport async function POST(request: Request) {\n  const accessToken = await requirePortalAccessToken();\n  if (!accessToken) {\n    return safeJson(\n      { error: { code: \"unauthorized\", message: \"Sign in required.\" } },\n      401\n    );\n  }\n\n  const payload: unknown = await request.json().catch(() => null);\n  const input =\n    payload !== null && typeof payload === \"object\"\n      ? (payload as Record<string, unknown>)\n      : {};\n  const name = typeof input.name === \"string\" ? input.name.trim() : \"\";\n  const rawFilters =\n    input.filters !== null && typeof input.filters === \"object\"\n      ? (input.filters as Record<string, unknown>)\n      : {};\n  const filters: Record<string, unknown> = {};\n  if (\n    rawFilters.lead_temp === \"hot\" ||\n    rawFilters.lead_temp === \"warm\" ||\n    rawFilters.lead_temp === \"cold\"\n  ) {\n    filters.lead_temp = rawFilters.lead_temp;\n  }\n  if (rawFilters.status === \"open\" || rawFilters.status === \"closed\") {\n    filters.status = rawFilters.status;\n  }\n  if (\n    typeof rawFilters.idle_days === \"number\" &&\n    Number.isInteger(rawFilters.idle_days) &&\n    rawFilters.idle_days >= 1 &&\n    rawFilters.idle_days <= 365\n  ) {\n    filters.idle_days = rawFilters.idle_days;\n  }\n  if (typeof rawFilters.tag === \"string\" && rawFilters.tag.trim()) {\n    filters.tag = rawFilters.tag.trim().slice(0, 32);\n  }\n  if (!name || Object.keys(filters).length === 0) {\n    return safeJson(\n      {\n        error: {\n          code: \"bad_request\",\n          message: \"A name and at least one filter are required.\",\n        },\n      },\n      400\n    );\n  }\n\n  try {\n    const result = await createSegment(\n      accessToken,\n      name,\n      filters as Parameters<typeof createSegment>[2]\n    );\n    if (result.kind === \"ok\") {\n      return safeJson({ ok: true, segment: result.segment ?? null }, 200);\n    }\n    if (result.kind === \"invalid\") {\n      return safeJson(\n        {\n          error: {\n            code: \"bad_request\",\n            message: \"Pick at least one valid filter.\",\n          },\n        },\n        400\n      );\n    }\n    return safeJson(\n      { error: { code: \"portal_unavailable\", message: \"Try again shortly.\" } },\n      503\n    );\n  } catch (error) {\n    if (error instanceof ControlPlaneRequestError && error.isUnauthorized) {\n      return safeJson(\n        { error: { code: \"unauthorized\", message: \"Session expired.\" } },\n        401\n      );\n    }\n    return safeJson(\n      { error: { code: \"portal_unavailable\", message: \"Try again shortly.\" } },\n      503\n    );\n  }\n}\n");


